# The model is expected to have a predict_proba or predict method returning a score in [-1,1]
# For safety, we try predict first, then fallback to predict_proba if available.

def _get_score(text: str) -> float:
    try:
        # Some models return a single float directly
        score = _model.predict([text])[0]
    except Exception:
        try:
            # If predict_proba returns probabilities for classes [-1,1]
            probs = _model.predict_proba([text])[0]
            # Assume classes are sorted as [-1, 1] or similar
            classes = _model.classes_ if hasattr(_model, "classes_") else None
            if classes is not None and len(classes) == 2:
                # Weighted average
                score = probs[0] * classes[0] + probs[1] * classes[1]
            else:
                # Fallback: take logit or mean
                score = probs.mean()
        except Exception as e:
            raise RuntimeError("Model failed to predict sentiment") from e
    return float(score)

def sentiment(text: str) -> float:
    """Sentiment score in [-1, 1] from the trained model at models/sentiment_v3.pkl, rounded to 3 decimals."""
